#!/usr/bin/env python3
"""pasang_tema_cerah.py - mengganti tampilan antarmuka web menjadi tema terang.

    python3 ~/projects/alat/pasang_tema_cerah.py

Yang diubah:
  ~/projects/antarmuka/frontend/gaya.css     diganti tema terang (cadangan: gaya.css.sebelum_cerah)
  ~/projects/alat/pasang_antarmuka.py        isi gaya.css di dalamnya ikut diganti, supaya pemasangan
                                             ulang antarmuka tidak mengembalikan tema gelap
                                             (cadangan: pasang_antarmuka.py.sebelum_cerah)
Hanya tampilan. Backend, pipeline, dan data tidak berubah. Muat ulang halaman (Ctrl+Shift+R) setelah memasang.
"""
import json, os, re, shutil, sys

CSS = json.loads(r'''"/* ==========================================================================\n   Tema terang antarmuka Penghitung Kendaraan 3D.\n   Selalu terang, tidak mengikuti mode gelap sistem operasi.\n   Warna kelas kendaraan (hijau, kuning, merah, biru) datang dari server, bukan dari sini.\n   ========================================================================== */\n:root {\n  color-scheme: light;\n  --latar: #f3f6fa;          /* latar halaman */\n  --kartu: #ffffff;          /* latar kartu */\n  --lembut: #f7f9fc;         /* latar isian, kepala tabel */\n  --teks: #1c2430;\n  --redup: #5b6878;\n  --garis: #dfe5ee;\n  --aksen: #1f63d6;          /* biru utama: tombol, tautan, tab aktif */\n  --aksen-gelap: #174ea9;\n  --aksen-muda: #e8f0fd;     /* sorotan baris, tab aktif */\n  --aksen-teks: #ffffff;\n  --hijau: #1a8a4a;\n  --galat: #c0352b;\n  --peringatan-latar: #fff6db;\n  --peringatan-garis: #f1d27a;\n  --peringatan-teks: #6b4e00;\n  --bayang: 0 1px 2px rgba(20, 35, 60, .06), 0 2px 8px rgba(20, 35, 60, .05);\n  --sudut: 12px;\n}\n\n* { box-sizing: border-box; }\nhtml { background: var(--latar); }\nbody {\n  margin: 0; background: var(--latar); color: var(--teks);\n  font: 15px/1.55 system-ui, -apple-system, \"Segoe UI\", Roboto, \"Noto Sans\", Ubuntu, sans-serif;\n}\nh1 { font-size: 20px; margin: 0; letter-spacing: -.01em; }\nh2 { font-size: 16px; margin: 0 0 12px; }\n.sub { margin: 2px 0 0; color: var(--redup); font-size: 13px; }\n.redup { color: var(--redup); font-size: 13px; margin: 6px 0; }\n.galat { color: var(--galat); font-size: 13px; margin: 8px 0 0; }\n.berhasil { color: var(--hijau); font-size: 13px; margin: 8px 0 0; }\n\n/* ---------- kepala dan navigasi ---------- */\n.atas {\n  display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap;\n  padding: 16px 24px; background: var(--kartu); border-top: 4px solid var(--aksen);\n}\n.lencana { font-size: 12px; color: var(--redup); background: var(--lembut); border: 1px solid var(--garis); border-radius: 999px; padding: 3px 10px; }\n.nav {\n  display: flex; gap: 6px; padding: 0 24px 12px; background: var(--kartu);\n  border-bottom: 1px solid var(--garis); overflow-x: auto;\n}\n.nav a {\n  padding: 7px 14px; color: var(--redup); text-decoration: none; font-size: 14px; white-space: nowrap;\n  border-radius: 999px; border: 1px solid transparent;\n}\n.nav a:hover { color: var(--teks); background: var(--lembut); }\n.nav a.aktif { color: var(--aksen); background: var(--aksen-muda); border-color: #c9dafa; font-weight: 600; }\n\n.peringatan {\n  max-width: 1280px; margin: 14px auto 0; padding: 10px 14px; border-radius: 10px; font-size: 13px;\n  background: var(--peringatan-latar); color: var(--peringatan-teks); border: 1px solid var(--peringatan-garis);\n}\n.peringatan p { margin: 2px 0; }\n\n/* ---------- tata letak ---------- */\n.halaman { max-width: 1280px; margin: 0 auto; padding: 20px 24px 48px; display: flex; flex-direction: column; gap: 16px; }\n.halaman[hidden] { display: none; }\n.dua { display: grid; grid-template-columns: 340px minmax(0, 1fr); gap: 16px; align-items: start; }\n.kolom { display: flex; flex-direction: column; gap: 16px; min-width: 0; }\n@media (max-width: 900px) { .dua { grid-template-columns: minmax(0, 1fr); } }\n@media (max-width: 820px) {\n  .halaman { padding: 14px 16px 32px; }\n  .atas { padding: 14px 16px; }\n  .nav { padding: 0 12px 10px; }\n  .peringatan { margin: 12px 16px 0; }\n}\n.kartu {\n  background: var(--kartu); border: 1px solid var(--garis); border-radius: var(--sudut);\n  padding: 18px; min-width: 0; box-shadow: var(--bayang);\n}\n.tengah { text-align: center; color: var(--redup); padding: 48px 16px; }\n.baris { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; }\n.baris > div { flex: 1 1 140px; min-width: 0; }\n.kisi2 { display: grid; grid-template-columns: 1fr 1fr; gap: 0 10px; }\n#hasil, #hasil_rinci { display: flex; flex-direction: column; gap: 16px; }\n#hasil[hidden], #hasil_rinci[hidden] { display: none; }\n\n/* ---------- formulir ---------- */\nlabel { display: block; font-size: 12px; font-weight: 500; color: var(--redup); margin: 12px 0 5px; }\nselect, input[type=number], input[type=text], input[type=date], input[type=search], input[type=file] {\n  width: 100%; padding: 8px 10px; border: 1px solid var(--garis); border-radius: 8px;\n  background: var(--kartu); color: var(--teks); font: inherit; font-size: 14px;\n}\ninput[type=file] { background: var(--lembut); }\nselect:focus, input:focus { outline: 2px solid #b9cff6; outline-offset: 0; border-color: var(--aksen); }\ninput[type=range] { width: 100%; accent-color: var(--aksen); }\ndetails { margin-top: 12px; }\nsummary { cursor: pointer; font-size: 13px; color: var(--aksen); }\n.geser { display: grid; grid-template-columns: 1fr 92px; gap: 8px; align-items: center; }\n.pilihan { display: flex; gap: 16px; font-size: 14px; margin: 6px 0; flex-wrap: wrap; }\n.pilihan label { display: inline-flex; align-items: center; gap: 6px; margin: 0; font-size: 14px; font-weight: 400; color: var(--teks); }\n.pilihan input { accent-color: var(--aksen); }\n\n/* ---------- tombol dan tautan ---------- */\nbutton { font: inherit; cursor: pointer; border-radius: 8px; }\n#tombol, .utamakan {\n  padding: 9px 16px; border: 0; background: var(--aksen); color: var(--aksen-teks); font-weight: 600;\n  box-shadow: 0 1px 2px rgba(31, 99, 214, .25);\n}\n#tombol { width: 100%; margin-top: 16px; }\n#tombol:hover, .utamakan:hover { background: var(--aksen-gelap); }\n#tombol:disabled, .utamakan:disabled { opacity: .6; cursor: default; }\n.polos { background: var(--kartu); border: 1px solid var(--garis); color: var(--teks); padding: 5px 11px; font-size: 13px; }\n.polos:hover { background: var(--lembut); border-color: #c8d1de; }\n.tautan { color: var(--aksen); font-size: 13px; text-decoration: none; font-weight: 500; }\n.tautan:hover { text-decoration: underline; }\n.kembali { background: none; border: 0; color: var(--aksen); padding: 0; font-size: 13px; font-weight: 500; align-self: flex-start; }\n\n/* ---------- daftar, status, jadwal ---------- */\n.riwayat { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; max-height: 340px; overflow-y: auto; }\n.riwayat .ket { display: block; font-size: 12px; color: var(--redup); }\n.status { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; }\n.lampu { width: 10px; height: 10px; border-radius: 50%; background: #c3ccd8; display: inline-block; }\n.lampu.hidup { background: var(--hijau); box-shadow: 0 0 0 3px #d6f0e1; }\n.jam { display: flex; gap: 6px; flex-wrap: wrap; margin: 10px 0 0; padding: 0; list-style: none; }\n.jam li { font-size: 12px; border: 1px solid var(--garis); background: var(--lembut); border-radius: 999px; padding: 2px 10px; font-variant-numeric: tabular-nums; }\n.jam li.sudah { background: var(--aksen-muda); border-color: #c9dafa; color: var(--aksen-gelap); }\ndl.rinci { display: grid; grid-template-columns: auto 1fr; gap: 6px 16px; margin: 0; font-size: 13px; }\ndl.rinci dt { color: var(--redup); }\ndl.rinci dd { margin: 0; font-weight: 500; }\n.tanda { font-size: 12px; border: 1px solid var(--garis); background: var(--lembut); border-radius: 999px; padding: 1px 9px; white-space: nowrap; }\n.tanda.otomatis { background: var(--aksen-muda); border-color: #c9dafa; color: var(--aksen-gelap); }\n.tanda.manual { background: #fff3e6; border-color: #f4d3ad; color: #8a4b0f; }\ncode {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; background: var(--lembut);\n  border: 1px solid var(--garis); border-radius: 4px; padding: 1px 5px; overflow-wrap: anywhere;\n}\n\n/* ---------- progres, galat ---------- */\n.batang { height: 10px; background: #e6ebf2; border-radius: 999px; overflow: hidden; margin-top: 12px; }\n#batang_isi { height: 100%; width: 0; background: var(--aksen); border-radius: 999px; transition: width .4s; }\npre {\n  white-space: pre-wrap; word-break: break-word; font-size: 12px; background: var(--lembut); border: 1px solid var(--garis);\n  border-radius: 8px; padding: 10px; max-height: 260px; overflow: auto;\n}\n\n/* ---------- hasil ---------- */\n.baris_judul { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }\n.baris_judul h2 { margin: 0; overflow-wrap: anywhere; }\n.aksi { display: flex; align-items: center; gap: 12px; }\nvideo, #pratinjau_gbr { width: 100%; border-radius: 8px; background: #0f141b; margin-top: 10px; aspect-ratio: 16 / 9; display: block; }\n.angka { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 12px; }\n.angka .kartu { padding: 14px 16px; }\n.angka .judul { font-size: 12px; color: var(--redup); display: flex; align-items: center; gap: 6px; }\n.angka .nilai { font-size: 30px; font-weight: 650; line-height: 1.2; font-variant-numeric: tabular-nums; margin-top: 2px; }\n.titik { width: 10px; height: 10px; border-radius: 3px; display: inline-block; flex: none; border: 1px solid rgba(0, 0, 0, .15); }\n#grafik svg { width: 100%; height: auto; display: block; }\n#grafik text { fill: var(--redup); font-size: 11px; }\n#grafik .sumbu { stroke: var(--garis); }\n.legenda { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px; color: var(--redup); margin-top: 8px; }\n.legenda span { display: inline-flex; align-items: center; gap: 5px; }\n\n/* ---------- tabel ---------- */\n.gulir { overflow-x: auto; border: 1px solid var(--garis); border-radius: 10px; }\ntable { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; }\nth {\n  text-align: left; color: var(--redup); font-weight: 600; font-size: 12px; padding: 9px 10px;\n  background: var(--lembut); border-bottom: 1px solid var(--garis); white-space: nowrap;\n}\ntd { padding: 9px 10px; border-bottom: 1px solid var(--garis); white-space: nowrap; }\ntbody tr:last-child td { border-bottom: 0; }\ntbody tr { cursor: pointer; }\ntbody tr:hover { background: var(--aksen-muda); }\ntbody tr.statis { cursor: default; }\ntbody tr.statis:hover { background: var(--lembut); }\n.kanan { text-align: right; }\ntd .titik { margin-right: 6px; vertical-align: baseline; }\ntd .polos, td .tautan { margin-left: 6px; }\ntd.aksi_sel { white-space: nowrap; text-align: right; }\n\n/* sebelum pratinjau pertama datang: kotak gelap kosong, tanpa ikon gambar rusak */\n#pratinjau_gbr:not([src]) { font-size: 0; color: transparent; }\n/* grafik tidak membesar berlebihan di layar lebar */\n#grafik svg { max-height: 300px; }\n"''')
PROYEK = os.path.expanduser("~/projects")
TUJUAN = os.path.join(PROYEK, "antarmuka", "frontend", "gaya.css")
PEMASANG = os.path.join(PROYEK, "alat", "pasang_antarmuka.py")

if not os.path.exists(TUJUAN):
    sys.exit("Tidak menemukan " + TUJUAN + " (pasang antarmuka dulu dengan alat/pasang_antarmuka.py).")
if open(TUJUAN, encoding="utf-8").read() == CSS:
    print("gaya.css sudah bertema terang.")
else:
    if not os.path.exists(TUJUAN + ".sebelum_cerah"):
        shutil.copy(TUJUAN, TUJUAN + ".sebelum_cerah")
    open(TUJUAN, "w", encoding="utf-8").write(CSS)
    print("ditulis:", TUJUAN.replace(os.path.expanduser("~"), "~"))

if os.path.exists(PEMASANG):
    teks = open(PEMASANG, encoding="utf-8").read()
    m = re.search(r"BERKAS = json\.loads\(r'''(.*?)'''\)", teks, re.S)
    if not m:
        print("(pasang_antarmuka.py tidak dikenali; tidak diubah)")
    else:
        berkas = json.loads(m.group(1))
        if berkas.get("frontend/gaya.css") == CSS:
            print("pasang_antarmuka.py sudah memuat tema terang.")
        else:
            berkas["frontend/gaya.css"] = CSS
            baru = teks[:m.start(1)] + json.dumps(berkas, ensure_ascii=True) + teks[m.end(1):]
            if not os.path.exists(PEMASANG + ".sebelum_cerah"):
                shutil.copy(PEMASANG, PEMASANG + ".sebelum_cerah")
            open(PEMASANG, "w", encoding="utf-8").write(baru)
            print("diperbarui:", PEMASANG.replace(os.path.expanduser("~"), "~"))

print("Selesai. Buka http://127.0.0.1:8000 lalu tekan Ctrl+Shift+R.")
